/// <summary>
/// The <c>AVASmmUtilityCls_Extension</c> contains the AVANADE extending logic for the <c>SmmUtility</c> class.
/// </summary>
[ExtensionOf(classStr(smmUtility))]
public final class AVASmmUtilityCls_Extension
{
}

Method.Source:
/// <summary>
/// designed by AVANADE
/// </summary>
/// <param name = "_common">common</param>
/// <param name = "_element">object</param>
/// <param name = "_create">boolean</param> 
public static void AVAopenSmmDocHandling(Common _common, Object _element, boolean _create = true)
{
    smmUtility::AVAopenMenuItemForm(menuItemDisplayStr(DocuView),_common,_element, _create, OpenMode::View);
}

/// <summary>
/// Open a form referenced by the menu item
/// </summary>
/// <param name="menuItemStr">
/// The menu item string
/// </param>
/// <param name="_record">
/// The record passed as args
/// </param>
/// <param name="_caller">
/// The caller object
/// </param>
/// <param name="_create">
/// Boolean to indicate creation
/// </param>
/// <param name="_openMode">
/// The mode to open the form in
/// </param>
static void AVAopenMenuItemForm(str menuItemStr, Common _record, Object _caller, boolean _create = false, OpenMode _openMode = OpenMode::Auto)
{
    MenuFunction    menuFunction;
    Args            args;
    FormRun         formRun;
    //FormDataSource  formDataSource;
    #Task

    menuFunction = new MenuFunction(menuItemStr,MenuItemType::Display);
    menuFunction.openMode(_openMode);

    // Check access rights
    if (!menuFunction || !menuFunction.checkAccessRights())
    {
        // Access rights are not sufficient to use this function.
        throw error("@SYS81158");
    }

    args         = new Args();
    args.record(_record);
    args.caller(_caller);


    formRun = menuFunction.create(args);

    if (formRun)
    {
        formRun.run();

        if (_create)
        {
            formRun.task(#taskNew);
        }

        if(menuItemStr != menuitemdisplaystr(DocuView)) 
        {
            formRun.wait();
        }
        else
        {
            formRun = menuFunction.create(args);    
        }
    }
    else
    {
        menuFunction.run(args);
    }
}
